#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int n, m;
    std::cin >> n >> m;
    if (n > m) std::swap(n, m);
    int product = n * m;
    std::map<int, int> lookup = {
        {1, (m % 6 > 1 && m % 6 < 5) ? 1 : 0},
        {2, ({2, 2}, {3, 1}, {7, 1})[m] ? ({2, 2}, {3, 1}, {7, 1})[m] : 0}
    };
    int lookup_n = lookup.count(n) ? lookup[n] : 0;
    int result = (~1 & (product - 2 * lookup_n));
    std::cout << result << std::endl;
    return 0;
}
